import React, { useState, useEffect } from "react";
import { Button, Form, Card, Alert, ListGroup } from "react-bootstrap";
import { authService } from "../../services";
import { useAuth } from "../../hooks/useAuth";

const MFASettings = () => {
  const { user } = useAuth();
  const [mfa, setMfa] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [backupCodes, setBackupCodes] = useState([]);
  const [type, setType] = useState("totp");

  useEffect(() => {
    if (user) {
      setLoading(true);
      authService
        .getMFAStatus(user.email)
        .then((res) => setMfa(res.data))
        .catch(() => setMfa(null))
        .finally(() => setLoading(false));
    }
  }, [user]);

  const handleSetup = async () => {
    setLoading(true);
    setMessage("");
    try {
      const res = await authService.setupMFA(user.email, type);
      setMfa(res.data.mfa);
      setMessage(res.data.message);
    } catch (e) {
      setMessage(e.response?.data?.message || "Error setting up MFA");
    }
    setLoading(false);
  };

  const handleGenerateBackupCodes = async () => {
    setLoading(true);
    setMessage("");
    try {
      const res = await authService.generateBackupCodes(user.email);
      setBackupCodes(res.data.backupCodes);
      setMessage("Backup codes generated");
    } catch (e) {
      setMessage(e.response?.data?.message || "Error generating backup codes");
    }
    setLoading(false);
  };

  return (
    <Card className="my-4">
      <Card.Body>
        <Card.Title>MFA Settings</Card.Title>
        {message && <Alert variant="info">{message}</Alert>}
        {loading ? (
          <div>Loading...</div>
        ) : (
          <>
            <div>
              Status: <strong>{mfa?.enabled ? "Enabled" : "Disabled"}</strong>
            </div>
            <div>
              Type: <strong>{mfa?.type || "-"}</strong>
            </div>
            {!mfa?.enabled && (
              <Form className="my-3">
                <Form.Group>
                  <Form.Label>MFA Type</Form.Label>
                  <Form.Select
                    value={type}
                    onChange={(e) => setType(e.target.value)}
                  >
                    <option value="totp">Authenticator App (TOTP)</option>
                    <option value="sms">SMS</option>
                  </Form.Select>
                </Form.Group>
                <Button className="mt-2" onClick={handleSetup}>
                  Enable MFA
                </Button>
              </Form>
            )}
            {mfa?.enabled && (
              <>
                <Button className="my-2" onClick={handleGenerateBackupCodes}>
                  Generate Backup Codes
                </Button>
                {backupCodes.length > 0 && (
                  <ListGroup className="my-2">
                    {backupCodes.map((code) => (
                      <ListGroup.Item key={code}>{code}</ListGroup.Item>
                    ))}
                  </ListGroup>
                )}
              </>
            )}
          </>
        )}
      </Card.Body>
    </Card>
  );
};

export default MFASettings;
