// Available teams
const availableTeams = [
  { id: 1, name: "Development", description: "Software development team" },
  { id: 2, name: "Operations", description: "Fleet operations team" },
  { id: 3, name: "Support", description: "Customer support team" },
  { id: 4, name: "Management", description: "Executive management team" },
];

// Available users not in teams
const availableUsers = [
  { id: 9, name: "Tom Wilson", email: "tom.wilson@company.com" },
  { id: 10, name: "Rachel Green", email: "rachel.green@company.com" },
  { id: 11, name: "Chris Martin", email: "chris.martin@company.com" },
];

const TeamMembers = () => {
  const [teamMembers, setTeamMembers] = useState(dummyTeamMembers);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedMember, setSelectedMember] = useState(null);
  const [search, setSearch] = useState("");
  const [teamFilter, setTeamFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");

  const filteredMembers = teamMembers.filter((member) => {
    const matchesSearch =
      member.fullName.toLowerCase().includes(search.toLowerCase()) ||
      member.email.toLowerCase().includes(search.toLowerCase()) ||
      member.teamName.toLowerCase().includes(search.toLowerCase());

    const matchesTeam = teamFilter === "ALL" || member.teamName === teamFilter;
    const matchesStatus =
      statusFilter === "ALL" || member.status === statusFilter;

    return matchesSearch && matchesTeam && matchesStatus;
  });

  const handleAssignMember = (assignmentData) => {
    const newMember = {
      id: Math.max(...teamMembers.map((m) => m.id)) + 1,
      ...assignmentData,
      status: "ACTIVE",
      joinedDate: new Date().toISOString().split("T")[0],
      permissions: ["fleet_oversight"],
      isTeamLead: false,
    };
    setTeamMembers([...teamMembers, newMember]);
    setShowAssignModal(false);
  };

  const handleRemoveMember = (memberId) => {
    setTeamMembers(teamMembers.filter((member) => member.id !== memberId));
  };

  const getRoleBadge = (role, isTeamLead) => {
    if (isTeamLead) {
      return <Badge bg="primary">Team Lead</Badge>;
    }
    const variants = {
      Developer: "info",
      Operator: "warning",
      "Support Agent": "secondary",
    };
    return <Badge bg={variants[role] || "secondary"}>{role}</Badge>;
  };

  const getUniqueTeams = () => {
    return [...new Set(teamMembers.map((member) => member.teamName))];
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Team Members Management</h2>
        <Button variant="primary" onClick={() => setShowAssignModal(true)}>
          <PersonAddIcon className="me-2" />
          Assign Member
        </Button>
      </div>

      {/* Filters */}
      <Card className="mb-4">
        <Card.Body>
          <Row>
            <Col md={4}>
              <Form.Group>
                <Form.Label>Search Members</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="Search by name, email, or team..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                />
              </Form.Group>
            </Col>
            <Col md={4}>
              <Form.Group>
                <Form.Label>Team</Form.Label>
                <Form.Select
                  value={teamFilter}
                  onChange={(e) => setTeamFilter(e.target.value)}
                >
                  <option value="ALL">All Teams</option>
                  {getUniqueTeams().map((team) => (
                    <option key={team} value={team}>
                      {team}
                    </option>
                  ))}
                </Form.Select>
              </Form.Group>
            </Col>
            <Col md={4}>
              <Form.Group>
                <Form.Label>Status</Form.Label>
                <Form.Select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                >
                  <option value="ALL">All Status</option>
                  <option value="ACTIVE">Active</option>
                  <option value="INACTIVE">Inactive</option>
                  <option value="PENDING">Pending</option>
                </Form.Select>
              </Form.Group>
            </Col>
          </Row>
        </Card.Body>
      </Card>

      {/* Team Members Table */}
      <Card>
        <Card.Body>
          <Table responsive striped hover>
            <thead>
              <tr>
                <th>Member</th>
                <th>Team</th>
                <th>Role</th>
                <th>Status</th>
                <th>Joined Date</th>
                <th>Permissions</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredMembers.map((member) => (
                <tr key={member.id}>
                  <td>
                    <div>
                      <strong>{member.fullName}</strong>
                      <br />
                      <small className="text-muted">{member.email}</small>
                    </div>
                  </td>
                  <td>
                    <Badge bg="light" text="dark">
                      {member.teamName}
                    </Badge>
                  </td>
                  <td>{getRoleBadge(member.role, member.isTeamLead)}</td>
                  <td>
                    <StatusBadge status={member.status} />
                  </td>
                  <td>
                    <small>
                      {new Date(member.joinedDate).toLocaleDateString()}
                    </small>
                  </td>
                  <td>
                    <div>
                      {member.permissions.map((permission) => (
                        <Badge
                          key={permission}
                          bg="info"
                          className="me-1"
                          style={{ fontSize: "0.7em" }}
                        >
                          {permission}
                        </Badge>
                      ))}
                    </div>
                  </td>
                  <td>
                    <div className="d-flex gap-1">
                      <Button
                        size="sm"
                        variant="outline-warning"
                        title="Edit Member"
                        onClick={() => {
                          setSelectedMember(member);
                          setShowEditModal(true);
                        }}
                      >
                        <EditIcon />
                      </Button>
                      <Button
                        size="sm"
                        variant="outline-danger"
                        title="Remove from Team"
                        onClick={() => handleRemoveMember(member.id)}
                      >
                        <DeleteIcon />
                      </Button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </Card.Body>
      </Card>

      {/* Team Statistics */}
      <Row className="mt-4">
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-primary">{teamMembers.length}</h4>
              <small className="text-muted">Total Members</small>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-success">
                {teamMembers.filter((m) => m.status === "ACTIVE").length}
              </h4>
              <small className="text-muted">Active Members</small>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-info">
                {new Set(teamMembers.map((m) => m.teamId)).size}
              </h4>
              <small className="text-muted">Teams with Members</small>
            </Card.Body>
          </Card>
        </Col>
        <Col md={3}>
          <Card className="text-center">
            <Card.Body>
              <h4 className="text-warning">
                {teamMembers.filter((m) => m.isTeamLead).length}
              </h4>
              <small className="text-muted">Team Leads</small>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Assign Member Modal */}
      <Modal show={showAssignModal} onHide={() => setShowAssignModal(false)} centered backdrop="static">
        <Modal.Header closeButton>
          <Modal.Title>Assign Member to Team</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Select User</Form.Label>
              <Form.Select>
                {availableUsers.map((user) => (
                  <option key={user.id} value={user.id}>
                    {user.name} ({user.email})
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Select Team</Form.Label>
              <Form.Select>
                {availableTeams.map((team) => (
                  <option key={team.id} value={team.id}>
                    {team.name} - {team.description}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Role</Form.Label>
              <Form.Select>
                <option value="Developer">Developer</option>
                <option value="Operator">Operator</option>
                <option value="Support Agent">Support Agent</option>
                <option value="Team Lead">Team Lead</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Check type="checkbox" label="Set as Team Lead" />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowAssignModal(false)}>
            Cancel
          </Button>
          <Button variant="primary">
            <PersonAddAlt1Icon className="me-2" />
            Assign Member
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Edit Member Modal */}
      <Modal show={showEditModal} onHide={() => setShowEditModal(false)}>
        <Modal.Header closeButton>
          <Modal.Title>Edit Team Member</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Member</Form.Label>
              <Form.Control
                type="text"
                value={selectedMember?.fullName}
                disabled
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Team</Form.Label>
              <Form.Select defaultValue={selectedMember?.teamId}>
                {availableTeams.map((team) => (
                  <option key={team.id} value={team.id}>
                    {team.name}
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Role</Form.Label>
              <Form.Select defaultValue={selectedMember?.role}>
                <option value="Developer">Developer</option>
                <option value="Operator">Operator</option>
                <option value="Support Agent">Support Agent</option>
                <option value="Team Lead">Team Lead</option>
              </Form.Select>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Status</Form.Label>
              <Form.Select defaultValue={selectedMember?.status}>
                <option value="ACTIVE">Active</option>
                <option value="INACTIVE">Inactive</option>
                <option value="PENDING">Pending</option>
              </Form.Select>
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowEditModal(false)}>
            Cancel
          </Button>
          <Button variant="primary">Update Member</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default TeamMembers;
