import { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';

export const useGeofences = (vehicleIds) => {
  const [geofences, setGeofences] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Mock geofence data - in real implementation, this would come from API
  useEffect(() => {
    if (!vehicleIds || vehicleIds.length === 0) {
      setGeofences([]);
      return;
    }

    // Mock data for demonstration
    const mockGeofences = [
      {
        id: '1',
        name: 'Office Zone',
        type: 'circle',
        coordinates: { lat: 40.7128, lng: -74.0060 },
        radius: 500,
        alertType: 'both',
        isActive: true,
        vehicles: vehicleIds,
        notifications: { email: true, push: true }
      },
      {
        id: '2',
        name: 'Warehouse Area',
        type: 'polygon',
        coordinates: [
          { lat: 40.7500, lng: -73.9800 },
          { lat: 40.7500, lng: -73.9700 },
          { lat: 40.7400, lng: -73.9700 },
          { lat: 40.7400, lng: -73.9800 }
        ],
        alertType: 'entry',
        isActive: true,
        vehicles: vehicleIds.slice(0, 2), // Only first 2 vehicles
        notifications: { email: true, push: false }
      }
    ];

    setGeofences(mockGeofences);
  }, [vehicleIds]);

  const createGeofence = async (geofenceData) => {
    setLoading(true);
    try {
      // Mock API call
      const newGeofence = {
        id: Date.now().toString(),
        ...geofenceData,
        vehicles: vehicleIds,
        isActive: true
      };
      
      setGeofences(prev => [...prev, newGeofence]);
      return newGeofence;
    } catch (err) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const updateGeofence = async (id, updates) => {
    setLoading(true);
    try {
      setGeofences(prev => 
        prev.map(g => g.id === id ? { ...g, ...updates } : g)
      );
    } catch (err) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const deleteGeofence = async (id) => {
    setLoading(true);
    try {
      setGeofences(prev => prev.filter(g => g.id !== id));
    } catch (err) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  const toggleGeofence = async (id) => {
    setLoading(true);
    try {
      setGeofences(prev => 
        prev.map(g => g.id === id ? { ...g, isActive: !g.isActive } : g)
      );
    } catch (err) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  return {
    geofences,
    alerts,
    loading,
    error,
    createGeofence,
    updateGeofence,
    deleteGeofence,
    toggleGeofence
  };
}; 