import React, { useState } from "react";
import { useParams } from "react-router-dom";
import { Tabs, Tab, Card } from "react-bootstrap";
import { useSelector } from "react-redux";
import VehicleAssignmentManager from "./VehicleAssignmentManagerPage";
import VehicleDocumentManager from "./VehicleDocumentManagerPage";
// import other managers as needed

const VehicleManagerPage = () => {
  const { vehicleId } = useParams();
  const { vehicles } = useSelector((state) => state.vehicle);
  const vehicle = vehicles.find((v) => v.vehicleId === vehicleId);
  const [tab, setTab] = useState("details");

  if (!vehicle) {
    return <Card className="mt-4"><Card.Body>Vehicle not found.</Card.Body></Card>;
  }

  return (
    <div className="container mt-4">
      <h4>Vehicle: {vehicle.registrationNumber} ({vehicle.year})</h4>
      <Tabs activeKey={tab} onSelect={setTab} className="mb-3">
        <Tab eventKey="details" title="Details">
          <Card><Card.Body>
            <div><b>VIN:</b> {vehicle.vin}</div>
            <div><b>Make:</b> {vehicle.make}</div>
            <div><b>Model:</b> {vehicle.model}</div>
            <div><b>Status:</b> {vehicle.status}</div>
            <div><b>Category:</b> {vehicle.category?.categoryName}</div>
          </Card.Body></Card>
        </Tab>
        <Tab eventKey="assignment" title="Assignment">
          <VehicleAssignmentManager vehicleId={vehicleId} />
        </Tab>
        <Tab eventKey="documents" title="Documents">
          <VehicleDocumentManager vehicleId={vehicleId} />
        </Tab>
        {/* Add more tabs for analytics, maintenance, etc. */}
      </Tabs>
    </div>
  );
};

export default VehicleManagerPage; 