const LOGIN_ATTEMPTS = [];

function getMockIP() {
  // Return a random mock IP for demonstration
  return `192.168.1.${Math.floor(Math.random() * 255)}`;
}

function findUserByEmail(email) {
  return MOCK_USERS.find((u) => u.email === email);
}

function generateMockJWT(user, sessionId) {
  // This is a mock JWT, not a real signed token
  const header = btoa(JSON.stringify({ alg: "RS256", typ: "JWT" }));
  const payload = btoa(
    JSON.stringify({
      sub: user.email,
      role: user.role,
      session: sessionId,
      exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24, // 24h expiry
    }),
  );
  const signature = "MOCKSIGNATURE";
  return `${header}.${payload}.${signature}`;
}

class AuthService {
  async login(email, password) {
    await new Promise((resolve) => setTimeout(resolve, 500));
    const found = findUserByEmail(email);
    const ip = getMockIP();
    let success = false;
    let message = "";
    if (!found) {
      message = "Invalid credentials";
      LOGIN_ATTEMPTS.push({
        email,
        success: false,
        timestamp: Date.now(),
        ip,
        message,
      });
      throw { response: { data: { message } } };
    }
    // Check lockout
    if (found.lockoutExpiry && Date.now() < found.lockoutExpiry) {
      message = "Account locked. Try again later.";
      LOGIN_ATTEMPTS.push({
        email,
        success: false,
        timestamp: Date.now(),
        ip,
        message,
      });
      throw { response: { data: { message } } };
    }
    if (found && found.password === password) {
      if (!found.user.emailVerified) {
        message = "Email not verified";
        LOGIN_ATTEMPTS.push({
          email,
          success: false,
          timestamp: Date.now(),
          ip,
          message,
        });
        throw { response: { data: { message } } };
      }
      if (found.user.approvalRequired && !found.user.approved) {
        message = "Awaiting admin approval";
        LOGIN_ATTEMPTS.push({
          email,
          success: false,
          timestamp: Date.now(),
          ip,
          message,
        });
        throw { response: { data: { message } } };
      }
      // Enforce max 3 concurrent sessions
      if (found.sessions.length >= 3) {
        // Remove the oldest session
        found.sessions.sort((a, b) => a.created - b.created);
        found.sessions.shift();
      }
      // Reset failed attempts
      found.failedLoginAttempts = 0;
      found.lockoutExpiry = null;
      // Simulate session token
      const sessionId = Date.now();
      const sessionToken = generateMockJWT(found.user, sessionId);
      found.sessions.push({ token: sessionToken, created: sessionId });
      localStorage.setItem("token", sessionToken);
      localStorage.setItem("user", JSON.stringify(found.user));
      success = true;
      LOGIN_ATTEMPTS.push({
        email,
        success: true,
        timestamp: Date.now(),
        ip,
        message: "Login successful",
      });
      // Return mfa status in user object
      return {
        data: { user: { ...found.user, mfa: found.mfa }, token: sessionToken },
      };
    }
    // Failed login attempt
    found.failedLoginAttempts = (found.failedLoginAttempts || 0) + 1;
    if (found.failedLoginAttempts >= 5) {
      found.lockoutExpiry = Date.now() + 15 * 60 * 1000; // 15 min lockout
    }
    message = "Invalid credentials";
    LOGIN_ATTEMPTS.push({
      email,
      success: false,
      timestamp: Date.now(),
      ip,
      message,
    });
    throw { response: { data: { message } } };
  }

  async register(userData) {
    await new Promise((resolve) => setTimeout(resolve, 500));
    if (findUserByEmail(userData.email)) {
      throw { response: { data: { message: "Email already registered" } } };
    }
    // Determine approval workflow
    let approvalRequired = false;
    let approved = true;
    let status = "pending";
    if (["fleet_manager", "gps_technician"].includes(userData.role)) {
      approvalRequired = true;
      approved = false;
      status = "pending";
    } else if (["driver", "customer"].includes(userData.role)) {
      approvalRequired = false;
      approved = true;
      status = "pending";
    } else if (userData.role === "admin") {
      approvalRequired = false;
      approved = true;
      status = "pending";
    }
    const newUser = {
      email: userData.email,
      password: userData.password,
      user: {
        id: MOCK_USERS.length + 1,
        name: userData.name,
        email: userData.email,
        role: userData.role,
        status,
        emailVerified: false,
        approvalRequired,
        approved,
      },
      token: "mock-token-" + (MOCK_USERS.length + 1),
      sessions: [],
      mfa: { enabled: false, type: null, secret: null, backupCodes: [] },
      passwordHistory: [userData.password],
      resetToken: null,
      resetTokenExpiry: null,
      failedLoginAttempts: 0,
      lockoutExpiry: null,
    };
    MOCK_USERS.push(newUser);
    // Simulate sending verification email
    return { data: { message: "Verification email sent", user: newUser.user } };
  }

  async verifyEmail(email) {
    const found = findUserByEmail(email);
    if (found) {
      found.user.emailVerified = true;
      found.user.status =
        found.user.approvalRequired && !found.user.approved
          ? "pending"
          : "active";
      return { data: { message: "Email verified" } };
    }
    throw { response: { data: { message: "User not found" } } };
  }

  async requestPasswordReset(email) {
    const found = findUserByEmail(email);
    if (found) {
      found.resetToken = "reset-" + Date.now();
      found.resetTokenExpiry = Date.now() + 30 * 60 * 1000; // 30 min
      // Simulate sending email
      return {
        data: {
          message: "Password reset email sent",
          resetToken: found.resetToken,
        },
      };
    }
    throw { response: { data: { message: "User not found" } } };
  }

  async resetPassword(email, resetToken, newPassword) {
    const found = findUserByEmail(email);
    if (
      found &&
      found.resetToken === resetToken &&
      Date.now() < found.resetTokenExpiry
    ) {
      if (found.passwordHistory.includes(newPassword)) {
        throw {
          response: { data: { message: "Cannot reuse previous password" } },
        };
      }
      found.password = newPassword;
      found.passwordHistory.unshift(newPassword);
      if (found.passwordHistory.length > 5) found.passwordHistory.pop();
      found.resetToken = null;
      found.resetTokenExpiry = null;
      return { data: { message: "Password reset successful" } };
    }
    throw { response: { data: { message: "Invalid or expired reset token" } } };
  }

  logout() {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
  }

  getCurrentUser() {
    const token = localStorage.getItem("token");
    const user = localStorage.getItem("user");
    if (token && user) {
      return Promise.resolve({ data: { user: JSON.parse(user), token } });
    }
    return null;
  }

  setAuthHeader(token) {
    // No-op for mock
  }

  getToken() {
    return localStorage.getItem("token");
  }

  // Session management (mock):
  async getSessions(email) {
    const found = findUserByEmail(email);
    if (found) {
      return { data: found.sessions };
    }
    throw { response: { data: { message: "User not found" } } };
  }

  async invalidateSession(email, sessionToken) {
    const found = findUserByEmail(email);
    if (found) {
      found.sessions = found.sessions.filter((s) => s.token !== sessionToken);
      return { data: { message: "Session invalidated" } };
    }
    throw { response: { data: { message: "User not found" } } };
  }

  // MFA (Multi-Factor Authentication) mock endpoints
  async getMFAStatus(email) {
    const found = findUserByEmail(email);
    if (found) {
      return { data: found.mfa };
    }
    throw { response: { data: { message: "User not found" } } };
  }

  async setupMFA(email, type) {
    const found = findUserByEmail(email);
    if (found) {
      found.mfa.enabled = true;
      found.mfa.type = type;
      found.mfa.secret = "MOCKTOTPSECRET";
      found.mfa.backupCodes = [
        "CODE1",
        "CODE2",
        "CODE3",
        "CODE4",
        "CODE5",
        "CODE6",
        "CODE7",
        "CODE8",
        "CODE9",
        "CODE10",
      ];
      return { data: { message: "MFA setup complete", mfa: found.mfa } };
    }
    throw { response: { data: { message: "User not found" } } };
  }

  async verifyMFA(email, code) {
    const found = findUserByEmail(email);
    if (found && found.mfa.enabled) {
      // Accept any code for mock, but simulate backup code usage
      if (found.mfa.backupCodes.includes(code)) {
        found.mfa.backupCodes = found.mfa.backupCodes.filter((c) => c !== code);
        return { data: { message: "MFA verified with backup code" } };
      }
      // Simulate TOTP/SMS always valid
      return { data: { message: "MFA verified" } };
    }
    throw {
      response: { data: { message: "MFA not enabled or user not found" } },
    };
  }

  async generateBackupCodes(email) {
    const found = findUserByEmail(email);
    if (found && found.mfa.enabled) {
      found.mfa.backupCodes = Array.from(
        { length: 10 },
        (_, i) => "CODE" + (i + 1),
      );
      return { data: { backupCodes: found.mfa.backupCodes } };
    }
    throw {
      response: { data: { message: "MFA not enabled or user not found" } },
    };
  }

  async emergencyBypassMFA(email) {
    const found = findUserByEmail(email);
    if (found && found.mfa.enabled) {
      // Simulate audit log
      return { data: { message: "Emergency MFA bypass granted and logged" } };
    }
    throw {
      response: { data: { message: "MFA not enabled or user not found" } },
    };
  }

  // Admin approval for Fleet Manager and GPS Technician
  async approveUser(email) {
    const found = findUserByEmail(email);
    if (found && found.user.approvalRequired) {
      found.user.approved = true;
      found.user.status = "active";
      return { data: { message: "User approved" } };
    }
    throw {
      response: {
        data: { message: "User not found or approval not required" },
      },
    };
  }

  getLoginAttempts(email) {
    return LOGIN_ATTEMPTS.filter((a) => a.email === email).sort(
      (a, b) => b.timestamp - a.timestamp,
    );
  }

  // Invalidate all sessions except the current one (for password change)
  async invalidateOtherSessions(email, currentToken) {
    const found = findUserByEmail(email);
    if (found) {
      found.sessions = found.sessions.filter((s) => s.token === currentToken);
      return { data: { message: "Other sessions invalidated" } };
    }
    throw { response: { data: { message: "User not found" } } };
  }
}

export const authService = new AuthService();
