import React, { useEffect, useRef, useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import { logout } from "../../slices/authSlice";
import { Modal, Button } from "react-bootstrap";
import { ROLES } from "../../routes/permissions";

const SESSION_TIMEOUTS = {
  [ROLES.ADMIN]: 15 * 60 * 1000, // 15 min
  default: 30 * 60 * 1000, // 30 min
};
const WARNING_BEFORE = 5 * 60 * 1000; // 5 min

const getTimeoutForRole = (role) =>
  SESSION_TIMEOUTS[role] || SESSION_TIMEOUTS.default;

const SessionManager = () => {
  const { isAuthenticated, user } = useSelector((state) => state.auth);
  const dispatch = useDispatch();
  const [showWarning, setShowWarning] = useState(false);
  const [timeLeft, setTimeLeft] = useState(null);
  const warningTimeoutRef = useRef();
  const logoutTimeoutRef = useRef();

  // Update last action timestamp on user activity
  useEffect(() => {
    if (!isAuthenticated) return;
    const updateActivity = () => {
      localStorage.setItem("lastAction", Date.now());
    };
    window.addEventListener("mousemove", updateActivity);
    window.addEventListener("keydown", updateActivity);
    window.addEventListener("click", updateActivity);
    return () => {
      window.removeEventListener("mousemove", updateActivity);
      window.removeEventListener("keydown", updateActivity);
      window.removeEventListener("click", updateActivity);
    };
  }, [isAuthenticated]);

  // Session timeout logic
  useEffect(() => {
    if (!isAuthenticated || !user) return;
    const timeout = getTimeoutForRole(user.role);
    const checkSession = () => {
      const lastAction =
        parseInt(localStorage.getItem("lastAction"), 10) || Date.now();
      const now = Date.now();
      const expiresAt = lastAction + timeout;
      const warningAt = expiresAt - WARNING_BEFORE;
      const msToWarning = warningAt - now;
      const msToLogout = expiresAt - now;
      if (msToWarning <= 0 && msToLogout > 0) {
        setShowWarning(true);
        setTimeLeft(Math.ceil(msToLogout / 1000));
        warningTimeoutRef.current = null;
        logoutTimeoutRef.current = setTimeout(() => {
          setShowWarning(false);
          dispatch(logout());
        }, msToLogout);
      } else if (msToLogout <= 0) {
        setShowWarning(false);
        dispatch(logout());
      } else {
        setShowWarning(false);
        setTimeLeft(null);
        warningTimeoutRef.current = setTimeout(checkSession, msToWarning);
      }
    };
    checkSession();
    return () => {
      if (warningTimeoutRef.current) clearTimeout(warningTimeoutRef.current);
      if (logoutTimeoutRef.current) clearTimeout(logoutTimeoutRef.current);
    };
  }, [isAuthenticated, user, dispatch]);

  // Extend session
  const handleExtend = () => {
    localStorage.setItem("lastAction", Date.now());
    setShowWarning(false);
    setTimeLeft(null);
  };

  // Countdown timer for warning modal
  useEffect(() => {
    if (!showWarning || timeLeft === null) return;
    if (timeLeft <= 0) return;
    const interval = setInterval(() => {
      setTimeLeft((prev) => (prev > 0 ? prev - 1 : 0));
    }, 1000);
    return () => clearInterval(interval);
  }, [showWarning, timeLeft]);

  return (
    <Modal show={showWarning} backdrop="static" keyboard={false} centered>
      <Modal.Header>
        <Modal.Title>Session Expiring Soon</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        Your session will expire in {timeLeft} seconds due to inactivity.
        <br />
        Would you like to extend your session?
      </Modal.Body>
      <Modal.Footer>
        <Button variant="primary" onClick={handleExtend}>
          Extend Session
        </Button>
        <Button variant="danger" onClick={() => dispatch(logout())}>
          Logout Now
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default SessionManager;
