import React, { useState } from "react";
import {
  Table,
  Button,
  Form,
  Card,
  Row,
  Col,
  Badge,
  Modal,
  ButtonGroup,
  ToggleButton,
  Pagination,
} from "react-bootstrap";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddIcon from "@mui/icons-material/Add";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";

const dummyClients = [
  {
    id: 1,
    name: "Acme Corp",
    createdAt: "2023-01-10",
    enabled: true,
    activePlan: "Premium",
    contactPerson: "Alice Smith",
    billingDetails: "alice@acme.com, 123-456-7890, 123 Main St",
  },
  {
    id: 2,
    name: "Beta Solutions",
    createdAt: "2023-02-15",
    enabled: false,
    activePlan: "Basic",
    contactPerson: "Bob Johnson",
    billingDetails: "bob@beta.com, 555-123-4567, 456 Oak Ave",
  },
];

const PAGE_SIZE = 6;

const ClientListPage = () => {
  const [clients, setClients] = useState(dummyClients);
  const [showModal, setShowModal] = useState(false);
  const [editingClient, setEditingClient] = useState(null);
  const [view, setView] = useState("grid");
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");

  const filteredClients = clients.filter((client) =>
    client.name.toLowerCase().includes(search.toLowerCase()) ||
    client.contactPerson.toLowerCase().includes(search.toLowerCase())
  );

  const totalPages = Math.ceil(filteredClients.length / PAGE_SIZE);
  const pagedClients = filteredClients.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE
  );

  const handleSaveClient = (clientData) => {
    if (editingClient) {
      setClients(
        clients.map((client) =>
          client.id === editingClient.id ? { ...client, ...clientData } : client
        )
      );
    } else {
      const newClient = {
        id: Math.max(...clients.map((c) => c.id)) + 1,
        ...clientData,
        createdAt: new Date().toISOString().split("T")[0],
      };
      setClients([...clients, newClient]);
    }
    setShowModal(false);
    setEditingClient(null);
  };

  const handleDeleteClient = (clientId) => {
    setClients(clients.filter((client) => client.id !== clientId));
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Client Management</h2>
        <div className="d-flex align-items-center gap-2">
          <ButtonGroup>
            <Button
              variant={view === "grid" ? "primary" : "outline-primary"}
              onClick={() => setView("grid")}
              title="Grid View"
            >
              <ViewModuleIcon />
            </Button>
            <Button
              variant={view === "list" ? "primary" : "outline-primary"}
              onClick={() => setView("list")}
              title="List View"
            >
              <ViewListIcon />
            </Button>
          </ButtonGroup>
          <Button variant="primary" onClick={() => setShowModal(true)}>
            <AddIcon className="me-2" />
            Create Client
          </Button>
        </div>
      </div>
      <Form.Group className="mb-3">
        <Form.Control
          type="text"
          placeholder="Search clients by name or contact..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </Form.Group>
      {view === "grid" ? (
        <Row>
          {pagedClients.map((client) => (
            <Col key={client.id} lg={6} className="mb-4">
              <Card>
                <Card.Header className="d-flex justify-content-between align-items-center">
                  <div>
                    <h5 className="mb-0">{client.name}</h5>
                    <Badge bg={client.enabled ? "success" : "secondary"}>
                      {client.enabled ? "Enabled" : "Disabled"}
                    </Badge>
                  </div>
                  <div className="d-flex gap-1">
                    <Button
                      size="sm"
                      variant="outline-warning"
                      title="Edit Client"
                      onClick={() => {
                        setEditingClient(client);
                        setShowModal(true);
                      }}
                    >
                      <EditIcon />
                    </Button>
                    <Button
                      size="sm"
                      variant="outline-danger"
                      title="Delete Client"
                      onClick={() => handleDeleteClient(client.id)}
                    >
                      <DeleteIcon />
                    </Button>
                  </div>
                </Card.Header>
                <Card.Body>
                  <div><strong>Contact:</strong> {client.contactPerson}</div>
                  <div><strong>Active Plan:</strong> {client.activePlan}</div>
                  <div><strong>Billing:</strong> {client.billingDetails}</div>
                  <div><strong>Created At:</strong> {client.createdAt}</div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Contact</th>
                  <th>Active Plan</th>
                  <th>Billing</th>
                  <th>Enabled</th>
                  <th>Created At</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {pagedClients.map((client) => (
                  <tr key={client.id}>
                    <td>{client.name}</td>
                    <td>{client.contactPerson}</td>
                    <td>{client.activePlan}</td>
                    <td>{client.billingDetails}</td>
                    <td>
                      <Badge bg={client.enabled ? "success" : "secondary"}>
                        {client.enabled ? "Enabled" : "Disabled"}
                      </Badge>
                    </td>
                    <td>{client.createdAt}</td>
                    <td>
                      <div className="d-flex gap-1">
                        <Button
                          size="sm"
                          variant="outline-warning"
                          title="Edit Client"
                          onClick={() => {
                            setEditingClient(client);
                            setShowModal(true);
                          }}
                        >
                          <EditIcon />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline-danger"
                          title="Delete Client"
                          onClick={() => handleDeleteClient(client.id)}
                        >
                          <DeleteIcon />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
            {totalPages > 1 && (
              <div className="d-flex justify-content-center mt-3">
                <Pagination
                  currentPage={page}
                  totalPages={totalPages}
                  onPageChange={setPage}
                />
              </div>
            )}
          </Card.Body>
        </Card>
      )}
      <Modal
        show={showModal}
        onHide={() => {
          setShowModal(false);
          setEditingClient(null);
        }}
        size="lg"
        centered
        backdrop="static"
        style={{ zIndex: 2000 }}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            {editingClient ? "Edit Client" : "Create New Client"}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form
            onSubmit={(e) => {
              e.preventDefault();
              const form = e.target;
              const formData = {
                name: form.name.value,
                contactPerson: form.contactPerson.value,
                activePlan: form.activePlan.value,
                billingDetails: form.billingDetails.value,
                enabled: form.enabled.checked,
              };
              handleSaveClient(formData);
            }}
          >
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Client Name</Form.Label>
                  <Form.Control
                    name="name"
                    type="text"
                    placeholder="Enter client name"
                    defaultValue={editingClient?.name}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Contact Person</Form.Label>
                  <Form.Control
                    name="contactPerson"
                    type="text"
                    placeholder="Enter contact person"
                    defaultValue={editingClient?.contactPerson}
                    required
                  />
                </Form.Group>
              </Col>
            </Row>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Active Plan</Form.Label>
                  <Form.Control
                    name="activePlan"
                    type="text"
                    placeholder="Enter active plan"
                    defaultValue={editingClient?.activePlan}
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Billing Details</Form.Label>
                  <Form.Control
                    name="billingDetails"
                    type="text"
                    placeholder="Enter billing details"
                    defaultValue={editingClient?.billingDetails}
                  />
                </Form.Group>
              </Col>
            </Row>
            <Form.Group className="mb-3">
              <Form.Check
                name="enabled"
                type="checkbox"
                label="Enabled"
                defaultChecked={editingClient?.enabled}
              />
            </Form.Group>
            <div className="d-flex justify-content-end">
              <Button
                variant="secondary"
                onClick={() => {
                  setShowModal(false);
                  setEditingClient(null);
                }}
                className="me-2"
              >
                Cancel
              </Button>
              <Button variant="primary" type="submit">
                {editingClient ? "Update Client" : "Create Client"}
              </Button>
            </div>
          </Form>
        </Modal.Body>
      </Modal>
    </div>
  );
};

export default ClientListPage; 