import React, { useState } from "react";
import { Card, Button, Form, Alert, ListGroup, Spinner } from "react-bootstrap";
import { authService } from "../../services";
import { useAuth } from "../../hooks/useAuth";

const MFASetup = () => {
  const { user } = useAuth();
  const [step, setStep] = useState(1);
  const [type, setType] = useState("totp");
  const [code, setCode] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [backupCodes, setBackupCodes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [secret, setSecret] = useState("");

  const handleTypeSelect = (e) => {
    setType(e.target.value);
    setError("");
    setMessage("");
  };

  const handleSetup = async () => {
    setLoading(true);
    setError("");
    setMessage("");
    try {
      const res = await authService.setupMFA(user.email, type);
      setMessage(res.data.message);
      setSecret("MOCKTOTPSECRET"); // For TOTP, show secret (mock)
      setStep(2);
    } catch (e) {
      setError(e.response?.data?.message || "Error setting up MFA");
    }
    setLoading(false);
  };

  const handleVerify = async () => {
    setLoading(true);
    setError("");
    setMessage("");
    try {
      // Accept any code for mock
      await authService.verifyMFA(user.email, code);
      setMessage("MFA verified and enabled!");
      setStep(3);
      // Generate backup codes
      const res = await authService.generateBackupCodes(user.email);
      setBackupCodes(res.data.backupCodes);
    } catch (e) {
      setError(e.response?.data?.message || "Verification failed");
    }
    setLoading(false);
  };

  return (
    <div className="d-flex justify-content-center align-items-center min-vh-100 bg-light">
      <Card style={{ width: 400 }}>
        <Card.Body>
          <h3 className="mb-4 text-center">MFA Setup Wizard</h3>
          {message && <Alert variant="info">{message}</Alert>}
          {error && <Alert variant="danger">{error}</Alert>}
          {step === 1 && (
            <>
              <Form.Group className="mb-3">
                <Form.Label>Select MFA Type</Form.Label>
                <Form.Select value={type} onChange={handleTypeSelect}>
                  <option value="totp">Authenticator App (TOTP)</option>
                  <option value="sms">SMS (One-Time Code)</option>
                </Form.Select>
              </Form.Group>
              <Button
                onClick={handleSetup}
                disabled={loading}
                className="w-100"
              >
                {loading ? (
                  <Spinner animation="border" size="sm" />
                ) : (
                  "Continue"
                )}
              </Button>
            </>
          )}
          {step === 2 && (
            <>
              {type === "totp" && (
                <Alert variant="secondary">
                  Scan this QR code with your authenticator app (mock):
                  <br />
                  <strong>Secret:</strong> {secret}
                </Alert>
              )}
              {type === "sms" && (
                <Alert variant="secondary">
                  A one-time code has been sent to your registered phone (mock:
                  use any code).
                </Alert>
              )}
              <Form.Group className="mb-3">
                <Form.Label>Enter the code from your app/SMS</Form.Label>
                <Form.Control
                  value={code}
                  onChange={(e) => setCode(e.target.value)}
                />
              </Form.Group>
              <Button
                onClick={handleVerify}
                disabled={loading}
                className="w-100"
              >
                {loading ? (
                  <Spinner animation="border" size="sm" />
                ) : (
                  "Verify & Enable MFA"
                )}
              </Button>
            </>
          )}
          {step === 3 && (
            <>
              <Alert variant="success">
                MFA is now enabled on your account!
              </Alert>
              <div className="mb-2">
                Here are your backup codes (save them securely):
              </div>
              <ListGroup className="mb-3">
                {backupCodes.map((code) => (
                  <ListGroup.Item key={code}>{code}</ListGroup.Item>
                ))}
              </ListGroup>
              <Button href="/admin/dashboard" className="w-100">
                Go to Dashboard
              </Button>
            </>
          )}
        </Card.Body>
      </Card>
    </div>
  );
};

export default MFASetup;
