import React, { useState } from "react";
import {
  Table,
  Button,
  Form,
  Card,
  Row,
  Col,
  Badge,
  Modal,
  ButtonGroup,
  Pagination,
} from "react-bootstrap";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import AddIcon from "@mui/icons-material/Add";
import GroupIcon from "@mui/icons-material/Group";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";

const dummyGroups = [
  {
    id: 1,
    name: "Admins",
    description: "System administrators with full access",
    members: [
      { id: 1, name: "John Doe", email: "john.doe@company.com" },
      { id: 2, name: "Sarah Jones", email: "sarah.jones@company.com" },
    ],
    status: "ACTIVE",
    createdAt: "2023-01-10",
  },
  {
    id: 2,
    name: "Operators",
    description: "Operators with limited access",
    members: [
      { id: 3, name: "Jane Smith", email: "jane.smith@company.com" },
    ],
    status: "ACTIVE",
    createdAt: "2023-02-15",
  },
];

const availableUsers = [
  { id: 1, name: "John Doe", email: "john.doe@company.com" },
  { id: 2, name: "Sarah Jones", email: "sarah.jones@company.com" },
  { id: 3, name: "Jane Smith", email: "jane.smith@company.com" },
  { id: 4, name: "Mike Wilson", email: "mike.wilson@company.com" },
  { id: 5, name: "David Brown", email: "david.brown@company.com" },
];

const PAGE_SIZE = 6;

const GroupListPage = () => {
  const [groups, setGroups] = useState(dummyGroups);
  const [showModal, setShowModal] = useState(false);
  const [editingGroup, setEditingGroup] = useState(null);
  const [view, setView] = useState("grid");
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");

  const filteredGroups = groups.filter((group) =>
    group.name.toLowerCase().includes(search.toLowerCase()) ||
    group.description.toLowerCase().includes(search.toLowerCase())
  );

  const totalPages = Math.ceil(filteredGroups.length / PAGE_SIZE);
  const pagedGroups = filteredGroups.slice(
    (page - 1) * PAGE_SIZE,
    page * PAGE_SIZE
  );

  const handleSaveGroup = (groupData) => {
    if (editingGroup) {
      setGroups(
        groups.map((group) =>
          group.id === editingGroup.id ? { ...group, ...groupData } : group
        )
      );
    } else {
      const newGroup = {
        id: Math.max(...groups.map((g) => g.id)) + 1,
        ...groupData,
        createdAt: new Date().toISOString().split("T")[0],
        status: "ACTIVE",
      };
      setGroups([...groups, newGroup]);
    }
    setShowModal(false);
    setEditingGroup(null);
  };

  const handleDeleteGroup = (groupId) => {
    setGroups(groups.filter((group) => group.id !== groupId));
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Group Management</h2>
        <div className="d-flex align-items-center gap-2">
          <ButtonGroup>
            <Button
              variant={view === "grid" ? "primary" : "outline-primary"}
              onClick={() => setView("grid")}
              title="Grid View"
            >
              <ViewModuleIcon />
            </Button>
            <Button
              variant={view === "list" ? "primary" : "outline-primary"}
              onClick={() => setView("list")}
              title="List View"
            >
              <ViewListIcon />
            </Button>
          </ButtonGroup>
          <Button variant="primary" onClick={() => setShowModal(true)}>
            <AddIcon className="me-2" />
            Create Group
          </Button>
        </div>
      </div>
      <Form.Group className="mb-3">
        <Form.Control
          type="text"
          placeholder="Search groups by name or description..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </Form.Group>
      {view === "grid" ? (
        <Row>
          {pagedGroups.map((group) => (
            <Col key={group.id} lg={6} className="mb-4">
              <Card>
                <Card.Header className="d-flex justify-content-between align-items-center">
                  <div>
                    <h5 className="mb-0">{group.name}</h5>
                    <Badge bg={group.status === "ACTIVE" ? "success" : "secondary"}>
                      {group.status}
                    </Badge>
                  </div>
                  <div className="d-flex gap-1">
                    <Button
                      size="sm"
                      variant="outline-warning"
                      title="Edit Group"
                      onClick={() => {
                        setEditingGroup(group);
                        setShowModal(true);
                      }}
                    >
                      <EditIcon />
                    </Button>
                    <Button
                      size="sm"
                      variant="outline-danger"
                      title="Delete Group"
                      onClick={() => handleDeleteGroup(group.id)}
                    >
                      <DeleteIcon />
                    </Button>
                  </div>
                </Card.Header>
                <Card.Body>
                  <div><strong>Description:</strong> {group.description}</div>
                  <div><strong>Members:</strong> {group.members.length}</div>
                  <div className="mt-2">
                    {group.members.slice(0, 3).map((member) => (
                      <Badge key={member.id} bg="light" text="dark" className="me-1">
                        {member.name}
                      </Badge>
                    ))}
                    {group.members.length > 3 && (
                      <Badge bg="secondary">
                        +{group.members.length - 3} more
                      </Badge>
                    )}
                  </div>
                  <div className="d-flex justify-content-between text-muted mt-2">
                    <small>Created: {group.createdAt}</small>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Description</th>
                  <th>Status</th>
                  <th>Members</th>
                  <th>Created</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {pagedGroups.map((group) => (
                  <tr key={group.id}>
                    <td>{group.name}</td>
                    <td>{group.description}</td>
                    <td>
                      <Badge bg={group.status === "ACTIVE" ? "success" : "secondary"}>
                        {group.status}
                      </Badge>
                    </td>
                    <td>{group.members.length}</td>
                    <td>{group.createdAt}</td>
                    <td>
                      <div className="d-flex gap-1">
                        <Button
                          size="sm"
                          variant="outline-warning"
                          title="Edit Group"
                          onClick={() => {
                            setEditingGroup(group);
                            setShowModal(true);
                          }}
                        >
                          <EditIcon />
                        </Button>
                        <Button
                          size="sm"
                          variant="outline-danger"
                          title="Delete Group"
                          onClick={() => handleDeleteGroup(group.id)}
                        >
                          <DeleteIcon />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
            {totalPages > 1 && (
              <div className="d-flex justify-content-center mt-3">
                <Pagination
                  currentPage={page}
                  totalPages={totalPages}
                  onPageChange={setPage}
                />
              </div>
            )}
          </Card.Body>
        </Card>
      )}
      <Modal
        show={showModal}
        onHide={() => {
          setShowModal(false);
          setEditingGroup(null);
        }}
        size="lg"
        centered
        backdrop="static"
        style={{ zIndex: 2000 }}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            {editingGroup ? "Edit Group" : "Create New Group"}
          </Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form
            onSubmit={(e) => {
              e.preventDefault();
              const form = e.target;
              const formData = {
                name: form.name.value,
                description: form.description.value,
                members: Array.from(form.members.selectedOptions).map((opt) => {
                  const user = availableUsers.find((u) => u.id === Number(opt.value));
                  return user;
                }),
              };
              handleSaveGroup(formData);
            }}
          >
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Group Name</Form.Label>
                  <Form.Control
                    name="name"
                    type="text"
                    placeholder="Enter group name"
                    defaultValue={editingGroup?.name}
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Status</Form.Label>
                  <Form.Select
                    name="status"
                    defaultValue={editingGroup?.status || "ACTIVE"}
                  >
                    <option value="ACTIVE">Active</option>
                    <option value="INACTIVE">Inactive</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>
            <Form.Group className="mb-3">
              <Form.Label>Description</Form.Label>
              <Form.Control
                name="description"
                as="textarea"
                rows={2}
                placeholder="Enter group description"
                defaultValue={editingGroup?.description}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Members</Form.Label>
              <Form.Select
                name="members"
                multiple
                defaultValue={editingGroup?.members?.map((m) => m.id) || []}
                style={{ minHeight: 120 }}
              >
                {availableUsers.map((user) => (
                  <option key={user.id} value={user.id}>
                    {user.name} ({user.email})
                  </option>
                ))}
              </Form.Select>
            </Form.Group>
            <div className="d-flex justify-content-end">
              <Button
                variant="secondary"
                onClick={() => {
                  setShowModal(false);
                  setEditingGroup(null);
                }}
                className="me-2"
              >
                Cancel
              </Button>
              <Button variant="primary" type="submit">
                {editingGroup ? "Update Group" : "Create Group"}
              </Button>
            </div>
          </Form>
        </Modal.Body>
      </Modal>
    </div>
  );
};

export default GroupListPage; 