import React from "react";
import { useSelector, useDispatch } from "react-redux";
import { Toast } from "react-bootstrap";
import { removeAlert } from "../../slices/alertSlice";

const AlertSystem = () => {
  const { alerts } = useSelector((state) => state.alert || { alerts: [] });
  const dispatch = useDispatch();

  return (
    <div className="position-fixed top-0 end-0 p-3" style={{ zIndex: 9999 }}>
      {alerts.map((alert) => (
        <Toast
          key={alert.id}
          show={true}
          onClose={() => dispatch(removeAlert(alert.id))}
          delay={alert.duration}
          autohide
          className={`bg-${alert.type === "error" ? "danger" : alert.type}`}
        >
          <Toast.Header>
            <strong className="me-auto">
              {alert.type.charAt(0).toUpperCase() + alert.type.slice(1)}
            </strong>
          </Toast.Header>
          <Toast.Body className="text-white">{alert.message}</Toast.Body>
        </Toast>
      ))}
    </div>
  );
};

export default AlertSystem;
