import React, { useState, useEffect } from "react";
import {
  Card,
  Row,
  Col,
  Badge,
  Form,
  Button,
  Modal,
} from "react-bootstrap";
import ButtonGroup from "react-bootstrap/ButtonGroup";
import Table from "react-bootstrap/Table";
import ViewModuleIcon from "@mui/icons-material/ViewModule";
import ViewListIcon from "@mui/icons-material/ViewList";

const dummyAgents = [
  {
    id: 1,
    name: "Agent Smith",
    email: "smith@agency.com",
    billingAddress: "123 Matrix Lane, Cityville",
  },
  {
    id: 2,
    name: "Agent Johnson",
    email: "johnson@agency.com",
    billingAddress: "456 Neo Ave, Townsburg",
  },
];

// Dummy clients for each agent
const dummyAgentClients = {
  1: [
    {
      id: 101,
      name: "Acme Corp",
      email: "alice@acme.com",
      billingDetails: "123 Main St, alice@acme.com",
    },
    {
      id: 102,
      name: "Beta Solutions",
      email: "bob@beta.com",
      billingDetails: "456 Oak Ave, bob@beta.com",
    },
  ],
  2: [
    {
      id: 201,
      name: "Gamma LLC",
      email: "carol@gamma.com",
      billingDetails: "789 Pine Rd, carol@gamma.com",
    },
  ],
};

const AGENTS_KEY = "agentsData";
const AGENT_CLIENTS_KEY = "agentClientsData";

const loadAgents = () => {
  const data = localStorage.getItem(AGENTS_KEY);
  return data ? JSON.parse(data) : dummyAgents;
};
const loadAgentClients = () => {
  const data = localStorage.getItem(AGENT_CLIENTS_KEY);
  return data ? JSON.parse(data) : dummyAgentClients;
};

const saveAgents = (agents) => {
  localStorage.setItem(AGENTS_KEY, JSON.stringify(agents));
};
const saveAgentClients = (agentClients) => {
  localStorage.setItem(AGENT_CLIENTS_KEY, JSON.stringify(agentClients));
};

const AgentManagementPage = () => {
  const [agents, setAgents] = useState(loadAgents());
  const [search, setSearch] = useState("");
  const [view, setView] = useState("grid");
  const [showClientsModal, setShowClientsModal] = useState(false);
  const [selectedAgent, setSelectedAgent] = useState(null);
  const [agentClients, setAgentClients] = useState([]);
  const [showAddClient, setShowAddClient] = useState(false);
  const [newClient, setNewClient] = useState({ name: "", email: "", billingDetails: "" });
  const [showBillingModal, setShowBillingModal] = useState(false);
  const [selectedClient, setSelectedClient] = useState(null);
  const [billingForm, setBillingForm] = useState({
    billingAddress: "",
    invoiceEmail: "",
    paymentTerms: "",
    taxId: "",
    notes: "",
  });
  const [editClientIndex, setEditClientIndex] = useState(null);
  const [agentClientsMap, setAgentClientsMap] = useState(loadAgentClients());

  useEffect(() => {
    saveAgents(agents);
  }, [agents]);

  useEffect(() => {
    saveAgentClients(agentClientsMap);
  }, [agentClientsMap]);

  const filteredAgents = agents.filter((agent) =>
    agent.name.toLowerCase().includes(search.toLowerCase()) ||
    agent.email.toLowerCase().includes(search.toLowerCase())
  );

  // Placeholder for actions (edit, delete, view clients, configure billing)
  const handleViewClients = (agent) => {
    setSelectedAgent(agent);
    setAgentClients(agentClientsMap[agent.id] || []);
    setShowClientsModal(true);
  };
  const handleConfigureBilling = (agent) => {
    // TODO: Implement billing config for agent
    alert(`Configure billing for ${agent.name}`);
  };
  const handleEditAgent = (agent) => {
    // TODO: Implement edit agent
    alert(`Edit agent ${agent.name}`);
  };
  const handleDeleteAgent = (agentId) => {
    setAgents(agents.filter((a) => a.id !== agentId));
  };

  const updateAgentClients = (agentId, clients) => {
    setAgentClients(clients);
    setAgentClientsMap((prev) => {
      const updated = { ...prev, [agentId]: clients };
      return updated;
    });
  };

  const handleAddClient = () => {
    setShowAddClient(true);
    setNewClient({ name: "", email: "", billingDetails: "" });
  };

  const handleEditClient = (client, idx) => {
    setEditClientIndex(idx);
    setNewClient({ name: client.name, email: client.email, billingDetails: client.billingDetails });
    setShowAddClient(true);
  };

  const handleSaveNewClient = () => {
    if (!newClient.name || !newClient.email) return;
    let updatedClients;
    if (editClientIndex !== null) {
      // Edit mode
      updatedClients = agentClients.map((c, i) =>
        i === editClientIndex ? { ...c, ...newClient } : c
      );
    } else {
      // Add mode
      updatedClients = [...agentClients, { ...newClient, id: Date.now() }];
    }
    updateAgentClients(selectedAgent.id, updatedClients);
    setShowAddClient(false);
    setEditClientIndex(null);
  };

  const handleDeleteClient = (idx) => {
    const updatedClients = agentClients.filter((_, i) => i !== idx);
    updateAgentClients(selectedAgent.id, updatedClients);
  };

  const handleOpenBillingModal = (client) => {
    setSelectedClient(client);
    setBillingForm({
      billingAddress: client.billingAddress || "",
      invoiceEmail: client.invoiceEmail || "",
      paymentTerms: client.paymentTerms || "",
      taxId: client.taxId || "",
      notes: client.notes || "",
    });
    setShowBillingModal(true);
  };

  const handleBillingFormChange = (e) => {
    const { name, value } = e.target;
    setBillingForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSaveBilling = () => {
    if (!selectedAgent || !selectedClient) return;
    // Update client in agentClients and dummyAgentClients
    const updatedClients = agentClients.map((c) =>
      c.id === selectedClient.id ? { ...c, ...billingForm } : c
    );
    updateAgentClients(selectedAgent.id, updatedClients);
    setShowBillingModal(false);
    setSelectedClient(null);
  };

  const handleCloseBillingModal = () => {
    setShowBillingModal(false);
    setSelectedClient(null);
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2>Agent Management</h2>
        <ButtonGroup>
          <Button
            variant={view === "grid" ? "primary" : "outline-primary"}
            onClick={() => setView("grid")}
            title="Grid View"
          >
            <ViewModuleIcon />
          </Button>
          <Button
            variant={view === "list" ? "primary" : "outline-primary"}
            onClick={() => setView("list")}
            title="List View"
          >
            <ViewListIcon />
          </Button>
        </ButtonGroup>
      </div>
      <Form.Group className="mb-3">
        <Form.Control
          type="text"
          placeholder="Search agents by name or email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </Form.Group>
      {view === "grid" ? (
        <Row>
          {filteredAgents.map((agent) => (
            <Col key={agent.id} lg={6} className="mb-4">
              <Card>
                <Card.Header className="d-flex justify-content-between align-items-center">
                  <div>
                    <h5 className="mb-0">{agent.name}</h5>
                    <Badge bg="info">Agent</Badge>
                  </div>
                </Card.Header>
                <Card.Body>
                  <div><strong>Email:</strong> {agent.email}</div>
                  <div><strong>Billing Address:</strong> {agent.billingAddress}</div>
                  <div className="mt-3 d-flex gap-2">
                    <Button size="sm" onClick={() => handleViewClients(agent)} variant="outline-primary">View Clients</Button>
                    <Button size="sm" onClick={() => handleConfigureBilling(agent)} variant="outline-warning">Configure Billing</Button>
                    <Button size="sm" onClick={() => handleEditAgent(agent)} variant="outline-secondary">Edit</Button>
                    <Button size="sm" onClick={() => handleDeleteAgent(agent.id)} variant="outline-danger">Delete</Button>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      ) : (
        <Card>
          <Card.Body>
            <Table responsive striped hover>
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Billing Address</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredAgents.map((agent) => (
                  <tr key={agent.id}>
                    <td>{agent.name}</td>
                    <td>{agent.email}</td>
                    <td>{agent.billingAddress}</td>
                    <td>
                      <Button size="sm" onClick={() => handleViewClients(agent)} variant="outline-primary" className="me-1">View Clients</Button>
                      <Button size="sm" onClick={() => handleConfigureBilling(agent)} variant="outline-warning" className="me-1">Configure Billing</Button>
                      <Button size="sm" onClick={() => handleEditAgent(agent)} variant="outline-secondary" className="me-1">Edit</Button>
                      <Button size="sm" onClick={() => handleDeleteAgent(agent.id)} variant="outline-danger">Delete</Button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </Card.Body>
        </Card>
      )}

      <Modal show={showClientsModal} onHide={() => setShowClientsModal(false)} size="lg" centered backdrop="static">
        <Modal.Header closeButton>
          <Modal.Title>Clients for {selectedAgent?.name}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Button variant="success" className="mb-3" onClick={() => { setShowAddClient(true); setEditClientIndex(null); setNewClient({ name: '', email: '', billingDetails: '' }); }}>Add Client</Button>
          <Table responsive striped hover>
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                <th>Billing Details</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {agentClients.map((client, idx) => (
                <tr key={client.id}>
                  <td>{client.name}</td>
                  <td>{client.email}</td>
                  <td>{client.billingDetails}</td>
                  <td>
                    <Button size="sm" variant="outline-warning" onClick={() => handleOpenBillingModal(client)} className="me-1">
                      Configure Billing
                    </Button>
                    <Button size="sm" variant="outline-secondary" onClick={() => handleEditClient(client, idx)} className="me-1">
                      Edit
                    </Button>
                    <Button size="sm" variant="outline-danger" onClick={() => handleDeleteClient(idx)}>
                      Delete
                    </Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        </Modal.Body>
      </Modal>
      {/* Add/Edit Client Modal */}
      <Modal show={showAddClient} onHide={() => { setShowAddClient(false); setEditClientIndex(null); }} centered backdrop="static">
        <Modal.Header closeButton>
          <Modal.Title>{editClientIndex !== null ? 'Edit' : 'Add'} Client for {selectedAgent?.name}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Name</Form.Label>
              <Form.Control
                type="text"
                value={newClient.name}
                onChange={(e) => setNewClient({ ...newClient, name: e.target.value })}
                placeholder="Client Name"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Email</Form.Label>
              <Form.Control
                type="email"
                value={newClient.email}
                onChange={(e) => setNewClient({ ...newClient, email: e.target.value })}
                placeholder="Client Email"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Billing Details</Form.Label>
              <Form.Control
                type="text"
                value={newClient.billingDetails}
                onChange={(e) => setNewClient({ ...newClient, billingDetails: e.target.value })}
                placeholder="Billing Details"
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => { setShowAddClient(false); setEditClientIndex(null); }}>Cancel</Button>
          <Button variant="primary" onClick={handleSaveNewClient}>Save</Button>
        </Modal.Footer>
      </Modal>

      {/* Billing Config Modal */}
      <Modal show={showBillingModal} onHide={handleCloseBillingModal} centered backdrop="static">
        <Modal.Header closeButton>
          <Modal.Title>Configure Billing for {selectedClient?.name}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Form.Group className="mb-3">
              <Form.Label>Billing Address</Form.Label>
              <Form.Control
                type="text"
                name="billingAddress"
                value={billingForm.billingAddress}
                onChange={handleBillingFormChange}
                placeholder="Billing Address"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Invoice Email</Form.Label>
              <Form.Control
                type="email"
                name="invoiceEmail"
                value={billingForm.invoiceEmail}
                onChange={handleBillingFormChange}
                placeholder="Invoice Email"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Payment Terms</Form.Label>
              <Form.Control
                type="text"
                name="paymentTerms"
                value={billingForm.paymentTerms}
                onChange={handleBillingFormChange}
                placeholder="e.g. Net 30, Due on Receipt"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Tax ID</Form.Label>
              <Form.Control
                type="text"
                name="taxId"
                value={billingForm.taxId}
                onChange={handleBillingFormChange}
                placeholder="Tax ID"
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Notes</Form.Label>
              <Form.Control
                as="textarea"
                rows={2}
                name="notes"
                value={billingForm.notes}
                onChange={handleBillingFormChange}
                placeholder="Additional notes"
              />
            </Form.Group>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseBillingModal}>Cancel</Button>
          <Button variant="primary" onClick={handleSaveBilling}>Save</Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default AgentManagementPage; 