import React, { useState } from 'react';
import { useGeofences } from '../hooks/useGeofences';

const GeofenceManager = ({ vehicleIds, onGeofenceCreate }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [selectedGeofence, setSelectedGeofence] = useState(null);
  
  const {
    geofences,
    loading,
    error,
    createGeofence,
    updateGeofence,
    deleteGeofence,
    toggleGeofence
  } = useGeofences(vehicleIds);

  const handleCreateGeofence = async (geofenceData) => {
    try {
      await createGeofence(geofenceData);
      setIsCreating(false);
      onGeofenceCreate?.(geofenceData);
    } catch (err) {
      console.error('Failed to create geofence:', err);
    }
  };

  const handleDeleteGeofence = async (id) => {
    if (window.confirm('Are you sure you want to delete this geofence?')) {
      try {
        await deleteGeofence(id);
      } catch (err) {
        console.error('Failed to delete geofence:', err);
      }
    }
  };

  return (
    <div className="geofence-manager" style={{
      background: '#fff',
      border: '1px solid #e5e7eb',
      borderRadius: '8px',
      padding: '16px'
    }}>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginBottom: '16px'
      }}>
        <h3 style={{ margin: 0, fontSize: '18px', fontWeight: '600' }}>
          Geofences ({geofences.length})
        </h3>
        <button
          onClick={() => setIsCreating(true)}
          disabled={isCreating || loading}
          style={{
            background: '#3b82f6',
            color: 'white',
            border: 'none',
            padding: '8px 16px',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '14px',
            fontWeight: '500'
          }}
        >
          {isCreating ? 'Creating...' : 'Create Geofence'}
        </button>
      </div>

      {error && (
        <div style={{
          background: '#fef2f2',
          color: '#dc2626',
          padding: '12px',
          borderRadius: '6px',
          marginBottom: '16px',
          fontSize: '14px'
        }}>
          {error}
        </div>
      )}

      {isCreating && (
        <div style={{
          background: '#f0f9ff',
          border: '1px solid #0ea5e9',
          borderRadius: '6px',
          padding: '16px',
          marginBottom: '16px'
        }}>
          <h4 style={{ margin: '0 0 12px 0', fontSize: '16px' }}>
            Creating New Geofence
          </h4>
          <p style={{ margin: 0, color: '#0369a1', fontSize: '14px' }}>
            Click on the map to define the geofence boundaries. 
            You can create circular or polygon geofences.
          </p>
        </div>
      )}

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        {geofences.map(geofence => (
          <div key={geofence.id} style={{
            border: '1px solid #e5e7eb',
            borderRadius: '6px',
            padding: '12px',
            background: geofence.isActive ? '#f0fdf4' : '#f9fafb'
          }}>
            <div style={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center',
              marginBottom: '8px'
            }}>
              <div style={{ fontWeight: '600', fontSize: '14px' }}>
                {geofence.name}
              </div>
              <div style={{ display: 'flex', gap: '8px' }}>
                <button
                  onClick={() => toggleGeofence(geofence.id)}
                  style={{
                    background: geofence.isActive ? '#22c55e' : '#6b7280',
                    color: 'white',
                    border: 'none',
                    padding: '4px 8px',
                    borderRadius: '4px',
                    fontSize: '12px',
                    cursor: 'pointer'
                  }}
                >
                  {geofence.isActive ? 'Active' : 'Inactive'}
                </button>
                <button
                  onClick={() => setSelectedGeofence(geofence)}
                  style={{
                    background: '#3b82f6',
                    color: 'white',
                    border: 'none',
                    padding: '4px 8px',
                    borderRadius: '4px',
                    fontSize: '12px',
                    cursor: 'pointer'
                  }}
                >
                  Edit
                </button>
                <button
                  onClick={() => handleDeleteGeofence(geofence.id)}
                  style={{
                    background: '#ef4444',
                    color: 'white',
                    border: 'none',
                    padding: '4px 8px',
                    borderRadius: '4px',
                    fontSize: '12px',
                    cursor: 'pointer'
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
            
            <div style={{ fontSize: '12px', color: '#6b7280' }}>
              <div>Type: {geofence.type} • Alert: {geofence.alertType}</div>
              <div>Vehicles: {geofence.vehicles.length}</div>
              {geofence.type === 'circle' && geofence.radius && (
                <div>Radius: {geofence.radius}m</div>
              )}
            </div>
          </div>
        ))}
      </div>

      {geofences.length === 0 && !isCreating && (
        <div style={{ 
          textAlign: 'center', 
          color: '#6b7280', 
          padding: '20px',
          fontSize: '14px'
        }}>
          No geofences created yet. Click "Create Geofence" to get started.
        </div>
      )}
    </div>
  );
};

export default GeofenceManager; 