import axios from 'axios';

const API_BASE = '/api';

class TrackingWebSocket {
  constructor() {
    this.ws = null;
    this.subscribers = {};
  }

  connect(vehicleIds) {
    // Example: ws://localhost:4000/tracking?vehicles=1,2,3
    const url = `${process.env.REACT_APP_WS_URL || 'ws://localhost:4000/tracking'}?vehicles=${vehicleIds.join(',')}`;
    this.ws = new WebSocket(url);
    this.ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      const { type } = data;
      if (this.subscribers[type]) {
        this.subscribers[type].forEach(cb => cb(data));
      }
    };
  }

  subscribe(eventType, callback) {
    if (!this.subscribers[eventType]) {
      this.subscribers[eventType] = [];
    }
    this.subscribers[eventType].push(callback);
  }

  unsubscribe(eventType, callback) {
    if (this.subscribers[eventType]) {
      this.subscribers[eventType] = this.subscribers[eventType].filter(cb => cb !== callback);
    }
  }

  disconnect() {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
  }
}

export const trackingWebSocket = new TrackingWebSocket();

export const fetchHistoricalTracking = (vehicleId, start, end) => {
  return axios.get(`${API_BASE}/tracking/historical/${vehicleId}`, {
    params: { start, end },
  });
};

