import React from 'react';

const VehicleList = ({ vehicles = [], locations = {}, onVehicleSelect }) => {
  const getStatusColor = (vehicle) => {
    if (locations[vehicle.id]) return '#22c55e'; // Online
    return '#6b7280'; // Offline
  };

  const getStatusText = (vehicle) => {
    if (locations[vehicle.id]) return 'Online';
    return 'Offline';
  };

  return (
    <div className="vehicle-list" style={{
      background: '#fff',
      border: '1px solid #e5e7eb',
      borderRadius: '8px',
      padding: '16px',
      maxHeight: '500px',
      overflowY: 'auto'
    }}>
      <h3 style={{ margin: '0 0 16px 0', fontSize: '18px', fontWeight: '600' }}>
        Vehicles ({vehicles.length})
      </h3>
      
      {vehicles.length === 0 ? (
        <div style={{ textAlign: 'center', color: '#6b7280', padding: '20px' }}>
          No vehicles available
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {vehicles.map(vehicle => (
            <div 
              key={vehicle.id}
              onClick={() => onVehicleSelect?.(vehicle.id)}
              style={{
                display: 'flex',
                alignItems: 'center',
                padding: '12px',
                border: '1px solid #e5e7eb',
                borderRadius: '6px',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                background: locations[vehicle.id] ? '#f0fdf4' : '#fff'
              }}
              onMouseEnter={(e) => {
                e.target.style.background = locations[vehicle.id] ? '#dcfce7' : '#f9fafb';
              }}
              onMouseLeave={(e) => {
                e.target.style.background = locations[vehicle.id] ? '#f0fdf4' : '#fff';
              }}
            >
              <div style={{ 
                width: '8px', 
                height: '8px', 
                borderRadius: '50%', 
                backgroundColor: getStatusColor(vehicle),
                marginRight: '12px',
                flexShrink: 0
              }} />
              
              <div style={{ flex: 1 }}>
                <div style={{ 
                  fontWeight: '600', 
                  fontSize: '14px',
                  color: '#111827'
                }}>
                  {vehicle.name || vehicle.id}
                </div>
                <div style={{ 
                  fontSize: '12px', 
                  color: '#6b7280',
                  marginTop: '2px'
                }}>
                  {vehicle.licensePlate || 'No License Plate'}
                </div>
              </div>
              
              <div style={{ textAlign: 'right' }}>
                <div style={{ 
                  fontSize: '12px', 
                  color: getStatusColor(vehicle),
                  fontWeight: '500'
                }}>
                  {getStatusText(vehicle)}
                </div>
                {locations[vehicle.id] && (
                  <div style={{ 
                    fontSize: '11px', 
                    color: '#6b7280',
                    marginTop: '2px'
                  }}>
                    {new Date(locations[vehicle.id].timestamp).toLocaleTimeString()}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default VehicleList; 