import React, { useEffect, useState } from "react";
import { Button, Form, Spinner, Alert, ButtonGroup, ToggleButton } from "react-bootstrap";
import IconButton from '@mui/material/IconButton';
import Tooltip from '@mui/material/Tooltip';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import { useDispatch, useSelector } from "react-redux";
import { setVehicles, setLoading, setError } from "../../../slices/vehicleSlice";
import { getVehicles } from "../../../services/vehicle.service";
import DataTable from "../../../components/common/DataTable";
import CardGrid from "../../../components/common/CardGrid";
import PaginationComponent from "../../../components/common/Pagination";
import { useNavigate } from "react-router-dom";
import MoreVertIcon from '@mui/icons-material/MoreVert';
import VisibilityIcon from '@mui/icons-material/Visibility';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AssignmentIndIcon from '@mui/icons-material/AssignmentInd';
import DescriptionIcon from '@mui/icons-material/Description';
import { blue, green, red, orange, teal } from '@mui/material/colors';

const PAGE_SIZE = 5;

const VehicleList = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { vehicles, loading, error } = useSelector((state) => state.vehicle);
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [view, setView] = useState("list");
  const [anchorEl, setAnchorEl] = useState(null);
  const [menuVehicleId, setMenuVehicleId] = useState(null);

  useEffect(() => {
    dispatch(setLoading(true));
    getVehicles()
      .then((res) => {
        dispatch(setVehicles(res.data));
        dispatch(setLoading(false));
      })
      .catch((err) => {
        dispatch(setError(err?.response?.data?.message || "Failed to load vehicles"));
        dispatch(setLoading(false));
      });
  }, [dispatch]);

  const filtered = vehicles.filter(
    (v) =>
      v.registrationNumber.toLowerCase().includes(search.toLowerCase()) ||
      v.vin.toLowerCase().includes(search.toLowerCase()) ||
      v.make.toLowerCase().includes(search.toLowerCase()) ||
      v.model.toLowerCase().includes(search.toLowerCase()),
  );
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paged = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  // Action handlers
  const handleView = (vehicleId) => {
    navigate(`./${vehicleId}`);
  };
  const handleEdit = (vehicleId) => {
    navigate(`./edit/${vehicleId}`);
  };
  const handleDelete = (vehicleId) => {
    // TODO: Implement delete logic
    alert(`Delete vehicle ${vehicleId}`);
  };
  const handleAssign = (vehicleId) => {
    navigate(`./${vehicleId}/assignment`);
  };
  const handleDocs = (vehicleId) => {
    navigate(`./${vehicleId}/documents`);
  };
  const handleAdd = () => {
    navigate("./add");
  };
  const handleTracking = (vehicleId) => {
    navigate(`/vehicles/tracking`, { state: { vehicleId } });
  };

  // MUI Menu handlers
  const handleMenuOpen = (event, vehicleId) => {
    setAnchorEl(event.currentTarget);
    setMenuVehicleId(vehicleId);
  };
  const handleMenuClose = () => {
    setAnchorEl(null);
    setMenuVehicleId(null);
  };

  // DataTable columns
  const columns = [
    { title: "Reg. Number", dataIndex: "registrationNumber" },
    { title: "VIN", dataIndex: "vin" },
    { title: "Make", dataIndex: "make" },
    { title: "Model", dataIndex: "model" },
    { title: "Year", dataIndex: "year" },
    { title: "Status", dataIndex: "status" },
    { title: "Category", dataIndex: "category", render: (val, row) => row.category?.categoryName },
  ];

  const renderActionsMenu = (row) => (
    <>
      <IconButton onClick={(e) => handleMenuOpen(e, row.vehicleId)}>
        <MoreVertIcon />
      </IconButton>
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl) && menuVehicleId === row.vehicleId}
        onClose={handleMenuClose}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
      >
        <MenuItem onClick={() => { handleView(row.vehicleId); handleMenuClose(); }}>
          <Tooltip title="View"><VisibilityIcon sx={{ color: blue[600], mr: 1 }} /></Tooltip>View
        </MenuItem>
        <MenuItem onClick={() => { handleEdit(row.vehicleId); handleMenuClose(); }}>
          <Tooltip title="Edit"><EditIcon sx={{ color: green[600], mr: 1 }} /></Tooltip>Edit
        </MenuItem>
        <MenuItem onClick={() => { handleDelete(row.vehicleId); handleMenuClose(); }}>
          <Tooltip title="Delete"><DeleteIcon sx={{ color: red[600], mr: 1 }} /></Tooltip>Delete
        </MenuItem>
        <MenuItem onClick={() => { handleAssign(row.vehicleId); handleMenuClose(); }}>
          <Tooltip title="Assignment"><AssignmentIndIcon sx={{ color: orange[600], mr: 1 }} /></Tooltip>Assignment
        </MenuItem>
        <MenuItem onClick={() => { handleDocs(row.vehicleId); handleMenuClose(); }}>
          <Tooltip title="Documents"><DescriptionIcon sx={{ color: teal[600], mr: 1 }} /></Tooltip>Documents
        </MenuItem>
        <MenuItem onClick={() => { handleTracking(row.vehicleId); handleMenuClose(); }}>
          <Tooltip title="Tracking"><VisibilityIcon sx={{ color: blue[800], mr: 1 }} /></Tooltip>Tracking
        </MenuItem>
      </Menu>
    </>
  );

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <Form.Control
          style={{ maxWidth: 300 }}
          placeholder="Search vehicles..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(1);
          }}
        />
        <div className="d-flex align-items-center gap-2">
          <Button onClick={handleAdd}>Add Vehicle</Button>
          <ButtonGroup>
            <ToggleButton
              id="list-view"
              type="radio"
              variant={view === "list" ? "primary" : "outline-primary"}
              name="view"
              value="list"
              checked={view === "list"}
              onChange={() => setView("list")}
            >
              List
            </ToggleButton>
            <ToggleButton
              id="grid-view"
              type="radio"
              variant={view === "grid" ? "primary" : "outline-primary"}
              name="view"
              value="grid"
              checked={view === "grid"}
              onChange={() => setView("grid")}
            >
              Grid
            </ToggleButton>
          </ButtonGroup>
        </div>
      </div>
      {loading && <Spinner animation="border" />}
      {error && <Alert variant="danger">{error}</Alert>}
      {view === "list" ? (
        <DataTable
          columns={columns}
          data={paged}
          rowActions={renderActionsMenu}
        />
      ) : (
        <CardGrid
          items={paged}
          renderCard={(v) => (
            <div className="card h-100 p-3">
              <div className="mb-2"><b>{v.registrationNumber}</b> ({v.year})</div>
              <div>VIN: {v.vin}</div>
              <div>Make: {v.make}</div>
              <div>Model: {v.model}</div>
              <div>Status: {v.status}</div>
              <div>Category: {v.category?.categoryName}</div>
              <div className="d-flex gap-1 mt-2">
                {renderActionsMenu(v)}
              </div>
            </div>
          )}
        />
      )}
      {/* Pagination (shared for both views) */}
      <PaginationComponent
        currentPage={page}
        totalPages={totalPages}
        onPageChange={setPage}
      />
    </div>
  );
};

export default VehicleList;
